package com.cloudinfra.sdk.storage

import java.io.InputStream
import java.nio.file.Path
import java.nio.file.Paths
import java.security.MessageDigest
import java.time.Instant
import java.util.UUID
import java.util.concurrent.ConcurrentHashMap

data class AuditEntry(
    val timestamp: Instant,
    val principal: String,
    val action: String,
    val resource: String,
    val outcome: String,
    val metadata: Map<String, String> = emptyMap()
)

interface AuditLogger {
    fun log(entry: AuditEntry)
}

class InMemoryAuditLogger : AuditLogger {
    val entries = mutableListOf<AuditEntry>()
    override fun log(entry: AuditEntry) {
        synchronized(entries) { entries.add(entry) }
    }
}

data class UploadPolicy(
    val maxSizeBytes: Long = 10 * 1024 * 1024,
    val allowedExtensions: Set<String> = setOf("png", "jpg", "jpeg", "gif", "pdf", "txt"),
    val allowedContentTypes: Set<String> = setOf(
        "image/png", "image/jpeg", "image/gif", "application/pdf", "text/plain"
    ),
    val deniedPathPatterns: List<Regex> = listOf(
        Regex(".*\\.\\..*"),
        Regex(".*[\\x00-\\x1f].*")
    )
)

class ContentTypeResolver {
    private val extensionMap = mapOf(
        "png" to "image/png", "jpg" to "image/jpeg", "jpeg" to "image/jpeg",
        "gif" to "image/gif", "pdf" to "application/pdf", "txt" to "text/plain",
        "html" to "text/html", "jsp" to "application/x-jsp", "exe" to "application/octet-stream"
    )

    fun resolve(filename: String): String {
        val ext = filename.substringAfterLast('.', "").lowercase()
        return extensionMap[ext] ?: "application/octet-stream"
    }
}

class PathNormalizer {
    fun normalize(basePath: String, relativePath: String): Path {
        val base = Paths.get(basePath).normalize()
        val resolved = base.resolve(relativePath).normalize()
        require(resolved.startsWith(base)) { "Path traversal detected" }
        return resolved
    }

    fun extractFilename(path: String): String {
        return Paths.get(path).fileName?.toString() ?: path
    }
}

class UploadValidator(
    private val policy: UploadPolicy,
    private val contentTypeResolver: ContentTypeResolver
) {
    fun validateFilename(filename: String): ValidationResult {
        for (pattern in policy.deniedPathPatterns) {
            if (pattern.matches(filename)) {
                return ValidationResult(false, "Path pattern denied: $filename")
            }
        }
        return ValidationResult(true, "OK")
    }

    fun validateExtension(filename: String): ValidationResult {
        val ext = filename.substringAfterLast('.', "").lowercase()
        if (ext !in policy.allowedExtensions) {
            return ValidationResult(false, "Extension not allowed: $ext")
        }
        return ValidationResult(true, "OK")
    }

    fun validateContentType(declaredType: String, filename: String): ValidationResult {
        val resolvedType = contentTypeResolver.resolve(filename)
        if (declaredType !in policy.allowedContentTypes) {
            return ValidationResult(false, "Content type not allowed: $declaredType")
        }
        if (resolvedType !in policy.allowedContentTypes) {
            return ValidationResult(false, "Resolved content type not allowed: $resolvedType")
        }
        return ValidationResult(true, "OK")
    }

    fun validateSize(size: Long): ValidationResult {
        if (size > policy.maxSizeBytes) {
            return ValidationResult(false, "File too large: $size > ${policy.maxSizeBytes}")
        }
        return ValidationResult(true, "OK")
    }
}

data class ValidationResult(val valid: Boolean, val message: String)

data class StoredObject(
    val id: String,
    val originalFilename: String,
    val storedPath: String,
    val contentType: String,
    val size: Long,
    val checksum: String
)

class CloudStorageService(
    private val basePath: String,
    private val validator: UploadValidator,
    private val pathNormalizer: PathNormalizer,
    private val contentTypeResolver: ContentTypeResolver,
    private val auditLogger: AuditLogger
) {
    private val objectStore = ConcurrentHashMap<String, StoredObject>()

    fun uploadObject(
        principal: String,
        filename: String,
        declaredContentType: String,
        size: Long,
        inputStream: InputStream
    ): Result<StoredObject> {
        val sanitizedFilename = pathNormalizer.extractFilename(filename)

        val filenameValidation = validator.validateFilename(sanitizedFilename)
        if (!filenameValidation.valid) {
            auditLogger.log(AuditEntry(Instant.now(), principal, "UPLOAD", sanitizedFilename, "DENIED", mapOf("reason" to filenameValidation.message)))
            return Result.failure(SecurityException(filenameValidation.message))
        }

        val extensionValidation = validator.validateExtension(sanitizedFilename)
        if (!extensionValidation.valid) {
            auditLogger.log(AuditEntry(Instant.now(), principal, "UPLOAD", sanitizedFilename, "DENIED", mapOf("reason" to extensionValidation.message)))
            return Result.failure(SecurityException(extensionValidation.message))
        }

        val contentTypeValidation = validator.validateContentType(declaredContentType, sanitizedFilename)
        if (!contentTypeValidation.valid) {
            auditLogger.log(AuditEntry(Instant.now(), principal, "UPLOAD", sanitizedFilename, "DENIED", mapOf("reason" to contentTypeValidation.message)))
            return Result.failure(SecurityException(contentTypeValidation.message))
        }

        val sizeValidation = validator.validateSize(size)
        if (!sizeValidation.valid) {
            auditLogger.log(AuditEntry(Instant.now(), principal, "UPLOAD", sanitizedFilename, "DENIED", mapOf("reason" to sizeValidation.message)))
            return Result.failure(SecurityException(sizeValidation.message))
        }

        val objectId = UUID.randomUUID().toString()
        val storedFilename = "${objectId}_${sanitizedFilename}"
        val resolvedPath = pathNormalizer.normalize(basePath, storedFilename)

        val bytes = inputStream.readBytes()
        val actualSize = bytes.size.toLong()

        if (actualSize > size) {
            auditLogger.log(AuditEntry(Instant.now(), principal, "UPLOAD", sanitizedFilename, "DENIED", mapOf("reason" to "Actual size exceeds declared size")))
            return Result.failure(SecurityException("Actual size exceeds declared size"))
        }

        val checksum = MessageDigest.getInstance("SHA-256").digest(bytes).joinToString("") { "%02x".format(it) }

        val storedObject = StoredObject(
            id = objectId,
            originalFilename = sanitizedFilename,
            storedPath = resolvedPath.toString(),
            contentType = contentTypeResolver.resolve(sanitizedFilename),
            size = actualSize,
            checksum = checksum
        )

        objectStore[objectId] = storedObject
        auditLogger.log(AuditEntry(Instant.now(), principal, "UPLOAD", sanitizedFilename, "ALLOWED", mapOf("objectId" to objectId, "checksum" to checksum)))

        return Result.success(storedObject)
    }

    fun getObject(objectId: String): StoredObject? = objectStore[objectId]
}

fun createDefaultStorageService(basePath: String, auditLogger: AuditLogger): CloudStorageService {
    val policy = UploadPolicy()
    val contentTypeResolver = ContentTypeResolver()
    val pathNormalizer = PathNormalizer()
    val validator = UploadValidator(policy, contentTypeResolver)
    return CloudStorageService(basePath, validator, pathNormalizer, contentTypeResolver, auditLogger)
}
